  const payload = jwt.verify(token, opts.publicKey, { algorithms: ['RS256'] }) as Claims;
  if (payload.iss !== opts.issuer) throw new AuthError('bad issuer');
  if (payload.aud !== opts.audience) throw new AuthError('bad audience');
  if (payload.exp * 1000 < Date.now()) throw new AuthError('expired');
  return payload;
}

